TEST(ArcDslTest, a87f7484)
{
    std::vector<hodel::Grid> inputs, outputs;
    inputs.reserve(4);
    outputs.reserve(4);
    inputs.emplace_back(hodel::Grid{{3, 0, 0, 4, 0, 4, 2, 0, 0, 8, 0, 0, 1, 0, 0}, {0, 3, 3, 4, 4, 4, 0, 2, 2, 0, 8, 8, 0, 1, 1}, {0, 3, 0, 4, 0, 4, 0, 2, 0, 0, 8, 0, 0, 1, 0}});
    outputs.emplace_back(hodel::Grid{{4, 0, 4}, {4, 4, 4}, {4, 0, 4}});
    inputs.emplace_back(hodel::Grid{{2, 0, 0, 3, 0, 0, 7, 0, 7, 1, 0, 0}, {2, 0, 0, 3, 0, 0, 0, 7, 0, 1, 0, 0}, {0, 2, 2, 0, 3, 3, 7, 0, 7, 0, 1, 1}});
    outputs.emplace_back(hodel::Grid{{7, 0, 7}, {0, 7, 0}, {7, 0, 7}});
    inputs.emplace_back(hodel::Grid{{0, 7, 7}, {7, 7, 0}, {7, 0, 7}, {3, 0, 0}, {0, 3, 3}, {3, 0, 0}, {2, 0, 0}, {0, 2, 2}, {2, 0, 0}, {8, 0, 0}, {0, 8, 8}, {8, 0, 0}});
    outputs.emplace_back(hodel::Grid{{0, 7, 7}, {7, 7, 0}, {7, 0, 7}});
    inputs.emplace_back(hodel::Grid{{6, 0, 6}, {0, 6, 6}, {6, 0, 6}, {4, 0, 4}, {0, 4, 4}, {4, 0, 4}, {8, 8, 8}, {8, 0, 8}, {8, 8, 8}});
    outputs.emplace_back(hodel::Grid{{8, 8, 8}, {8, 0, 8}, {8, 8, 8}});

    auto const iFunction{[] () -> hodel::Grid { return hodel::Grid{}; }};
    aicpp::Neuron<hodel::Grid> iNeuron{"I", iFunction};
    Connection const I{&iNeuron, {}};
    Connection const ZERO{buildConnection("ZERO", {})};
    Connection const dmirror{buildConnection("dmirror", {})};
    Connection const identity{buildConnection("identity", {})};
    Connection const ofcolor{buildConnection("ofcolor", {})};
    Connection const x1{buildConnection("numcolors", {I})};
    Connection const x2{buildConnection("dmirror", {I})};
    Connection const x3{buildConnection("portrait", {I})};
    Connection const x4{buildConnection("branch", {x3, dmirror, identity})};
    Connection const x5{buildConnection("lbind", {x4, I})};
    Connection const x6{buildConnection("decrement", {x1})};
    Connection const x7{buildConnection("hsplit", {x5, x6})};
    Connection const x8{buildConnection("rbind", {ofcolor, ZERO})};
    Connection const x9{buildConnection("apply", {x8, x7})};
    Connection const x10{buildConnection("leastcommon", {x9})};
    Connection const x11{buildConnection("matcher", {x8, x10})};
    Connection const x12{buildConnection("extract", {x7, x11})};
    Connection const O{buildConnection("lbind", {x4, x12})};

    for (size_t i = 0; i < 4; ++i)
    {
        iNeuron.function() = [inputs, i] () -> hodel::Grid { return inputs[i]; };
        EXPECT_TRUE(outputs[i] == std::any_cast<hodel::Grid>(O.output()));
    }
}

