TEST(ArcDslTest, f9012d9b)
{
    std::vector<hodel::Grid> inputs, outputs;
    inputs.reserve(3);
    outputs.reserve(3);
    inputs.emplace_back(hodel::Grid{{8, 6, 0, 6}, {6, 8, 6, 8}, {8, 6, 8, 6}, {6, 8, 6, 8}});
    outputs.emplace_back(hodel::Grid{{8}});
    inputs.emplace_back(hodel::Grid{{2, 1, 2, 1, 2}, {1, 1, 1, 1, 1}, {2, 1, 2, 1, 2}, {0, 0, 1, 1, 1}, {0, 0, 2, 1, 2}});
    outputs.emplace_back(hodel::Grid{{1, 1}, {2, 1}});
    inputs.emplace_back(hodel::Grid{{2, 2, 5, 2, 2, 5, 2}, {2, 2, 5, 2, 2, 5, 2}, {5, 5, 5, 5, 5, 5, 5}, {2, 2, 5, 2, 2, 5, 2}, {2, 2, 5, 2, 2, 5, 2}, {5, 5, 5, 5, 5, 0, 0}, {2, 2, 5, 2, 2, 0, 0}});
    outputs.emplace_back(hodel::Grid{{5, 5}, {5, 2}});

    auto const iFunction{[] () -> hodel::Grid { return hodel::Grid{}; }};
    aicpp::Neuron<hodel::Grid> iNeuron{"I", iFunction};
    Connection const I{&iNeuron, {}};
    Connection const F{buildConnection("F", {})};
    Connection const ORIGIN{buildConnection("ORIGIN", {})};
    Connection const T{buildConnection("T", {})};
    Connection const TWO{buildConnection("TWO", {})};
    Connection const ZERO{buildConnection("ZERO", {})};
    Connection const contained{buildConnection("contained", {})};
    Connection const flip{buildConnection("flip", {})};
    Connection const multiply{buildConnection("multiply", {})};
    Connection const neighbors{buildConnection("neighbors", {})};
    Connection const palette{buildConnection("palette", {})};
    Connection const shift{buildConnection("shift", {})};
    Connection const x1{buildConnection("objects", {I, T, F, F})};
    Connection const x2{buildConnection("ofcolor", {I, ZERO})};
    Connection const x3{buildConnection("lbind", {contained, ZERO})};
    Connection const x4{buildConnection("chain", {flip, x3, palette})};
    Connection const x5{buildConnection("mfilter", {x1, x4})};
    Connection const x6{buildConnection("vsplit", {I, TWO})};
    Connection const x7{buildConnection("hsplit", {I, TWO})};
    Connection const x8{buildConnection("extract", {x6, x4})};
    Connection const x9{buildConnection("extract", {x7, x4})};
    Connection const x10{buildConnection("asobject", {x8})};
    Connection const x11{buildConnection("asobject", {x9})};
    Connection const x12{buildConnection("vperiod", {x10})};
    Connection const x13{buildConnection("hperiod", {x11})};
    Connection const x14{buildConnection("neighbors", {ORIGIN})};
    Connection const x15{buildConnection("mapply", {neighbors, x14})};
    Connection const x16{buildConnection("astuple", {x12, x13})};
    Connection const x17{buildConnection("rbind", {multiply, x16})};
    Connection const x18{buildConnection("apply", {x17, x15})};
    Connection const x19{buildConnection("lbind", {shift, x5})};
    Connection const x20{buildConnection("mapply", {x19, x18})};
    Connection const x21{buildConnection("paint", {I, x20})};
    Connection const O{buildConnection("subgrid", {x2, x21})};

    for (size_t i = 0; i < 3; ++i)
    {
        iNeuron.function() = [inputs, i] () -> hodel::Grid { return inputs[i]; };
        EXPECT_TRUE(outputs[i] == std::any_cast<hodel::Grid>(O.output()));
    }
}

